	SELECT CONCAT('CAF',
				  LPAD(COALESCE(CAST(SUBSTRING(CAFETERIA_ID, 4)AS UNSIGNED)),2026000) + 1, 7, '0'))


INSERT INTO CAFETERIA(
	CAFETERIA_ID
	, MEAL_DATE
	, MEAL_TYPE
	, MENU
	, MEAL_CLOSED
) VALUES

  	(
  		CONCAT('CAF',
  			   LPAD(CAST(#{CAFETERIA_ID} AS UNSIGNED) + 1, 7, '0'))
  		#{item.mealDate}
  		#{item.mealType}
  		#{item.meal}
  		#{item.mealClosed}
  	)
